import * as T from './vendor/three.module.js';
import {releaseModel} from './studio-models.js';
export function createTailoring(body,legs){const root=new T.Group();body.add(root);let key='',spec=null,mesh=null,rest=null,sleeping=false,rain=false;
 function set(v){const k=JSON.stringify(v);if(k===key)return;key=k;for(const c of [...root.children])releaseModel(c);spec=v;mesh=null;if(!v)return;const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const c=canvas.getContext('2d');c.fillStyle=v.color;c.fillRect(0,0,256,256);c.fillStyle=v.accent;if(v.pattern==='check'){c.globalAlpha=.45;c.fillRect(0,0,128,256);c.fillRect(0,0,256,128)}if(v.pattern==='stripe'){c.fillRect(0,0,256,40);c.fillRect(0,128,256,40)}if(v.pattern==='dots')for(const [x,y]of [[64,64],[192,192]]){c.beginPath();c.arc(x,y,18,0,Math.PI*2);c.fill()}c.globalAlpha=1;const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.repeat.set(2*Math.PI*.35/(v.patternScale*2),.5/(v.patternScale*2));const material=new T.MeshPhysicalMaterial({map:texture,roughness:.95,sheen:.6,side:T.DoubleSide});
 const rows=40,segments=96,positions=[],uv=[],indices=[],top=v.kind==='skirt'?.46:.715,bottom=v.kind==='top'?.46-v.length*.3:.46-v.length;
 for(let j=0;j<=rows;j++){const y=top+(bottom-top)*j/rows;const torso=y>.58?.289+(.715-y)*.30:.332+Math.max(0,.58-y)*.09;const t=Math.max(0,(.46-y)/v.length),r=y>=.46?torso:.348+v.flare*t;for(let i=0;i<=segments;i++){const a=i/segments*Math.PI*2,fold=v.pleats?Math.cos(a*v.pleats)*.01*t:0;positions.push(Math.sin(a)*(r+fold),y,Math.cos(a)*(r+fold)*.84);uv.push(i/segments,j/rows)}}for(let j=0;j<rows;j++)for(let i=0;i<segments;i++){const a=j*(segments+1)+i,b=a+segments+1;indices.push(a,b,a+1,b,b+1,a+1)}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeVertexNormals();mesh=new T.Mesh(g,material);mesh.castShadow=mesh.receiveShadow=true;root.add(mesh);rest=Float32Array.from(positions);tick()}
 function tick(){root.visible=!!spec&&!sleeping&&!rain;if(!mesh||!root.visible)return;const sit=T.MathUtils.clamp(-Math.min(...legs.map(x=>x.rotation.x))/1.15,0,1),p=mesh.geometry.attributes.position;for(let i=0;i<p.count;i++){const x=rest[i*3],y=rest[i*3+1],z=rest[i*3+2],t=Math.max(0,(.46-y)/spec.length),front=T.MathUtils.smoothstep(z,-.03,.25);p.setXYZ(i,x,y+sit*t*front*.26,z+sit*t*front*.18)}p.needsUpdate=true;mesh.geometry.computeVertexNormals();mesh.geometry.computeBoundingSphere()}
 return {set,tick,sleep(v){sleeping=v;tick()},rain(v){rain=v;tick()}};
}
